-- Поради від Джері: короткі корисні речі про бізнес, маркетинг, продажі, переговори, терміни, факти.
-- Показуються під час роботи віконцем біля робота; Саша відповідає «знав / нове / не цікаво / детальніше».
CREATE TABLE tips (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  topic TEXT NOT NULL DEFAULT 'business',
  title TEXT NOT NULL,
  body TEXT NOT NULL,
  source TEXT NOT NULL DEFAULT 'seed',      -- seed | jerry (згенерував сам) | chat (Джері записав у розмові)
  shown_count INTEGER NOT NULL DEFAULT 0,
  shown_at TEXT,
  reaction TEXT,                            -- knew | new | boring | more
  reacted_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX tips_shown ON tips(shown_count, id);


'Поки працюєш, Джері час від часу виринає біля робота з короткою порадою: бізнес, маркетинг, реклама, продажі, переговори, важкі терміни простими словами, цікаві факти. Відповідай кнопками: «Знав», «Нове для мене», «Не цікаво», «Детальніше» (відкриє розмову). Під твої відповіді він підбирає теми, а коли нові поради закінчуються — сам пише ще (≈1–2 цента за пачку). Частота і тумблери — Налаштування → «Можливості». Джері в розмові може записати пораду в базу (tip_add) і бачить, що тобі цікаво (tips_stats).',
'2026-10-31 20:00:00');
