INSERT INTO tips (topic, title, body) VALUES
('finance', 'CAC — ціна клієнта, а не ліда', 'CAC = усі витрати на рекламу і продажі за період ÷ кількість нових клієнтів. Ціна ліда — це ще не клієнт. Питай у клієнта: «Скільки вам коштує один покупець?» — так розмова переходить з «дорогі ліди» на гроші.'),
('finance', 'LTV і правило 3 до 1', 'LTV — скільки грошей клієнт приносить за весь час співпраці. Орієнтир: LTV хоча б утричі більший за CAC — здорово. Якщо LTV менший за CAC — бізнес доплачує за кожного клієнта, і реклама тут не врятує.'),
('term', 'ROAS проти ROMI', 'ROAS = виручка ÷ витрати на рекламу (ROAS 4 — на 1 грн реклами 4 грн виручки). ROMI рахує прибуток: (прибуток з реклами − витрати) ÷ витрати. ROAS 4 при маржі 20% — це мінус. Завжди питай маржу.'),
('finance', 'Допустима ціна ліда', 'Максимум за лід у нуль = середній чек × маржа × конверсія з ліда в продаж. Чек 10 000, маржа 30%, конверсія 20% → 600 грн. Порахуй це з клієнтом на старті — і суперечки «чому ліди дорогі» зникають.'),
('term', 'Націнка ≠ маржа', 'Купив за 100, продав за 200: націнка 100%, а маржа 50%. Клієнти часто плутають і переоцінюють, скільки можуть платити за лід. Уточнюй, про що саме мова.'),
('term', 'Юніт-економіка', 'Рахуєш гроші на одну одиницю: одного клієнта, одне замовлення. Якщо на одиниці мінус — масштабування тільки збільшить збиток. Спершу плюс на одиниці, потім бюджет.'),
('term', 'Churn — відтік', 'Відсоток клієнтів, що пішли за період. 5% на місяць звучить дрібно, але за рік лишиться лише ~54% (0,95¹²). Утримати клієнта майже завжди дешевше, ніж знайти нового.'),
('term', 'MRR — регулярний дохід', 'MRR — щомісячний повторюваний дохід. Для тебе — сума абонплат клієнтів. Разові проєкти дають сплески, MRR дає спокій. Корисно бачити обидві цифри окремо.'),
('term', 'Payback — термін окупності', 'За скільки місяців повертається CAC: CAC ÷ місячний прибуток з клієнта. CAC 3000, прибуток 1000 на місяць → 3 місяці. Якщо клієнт іде раніше — ти в мінусі.'),
('term', 'NPS', '«Наскільки ймовірно, що порекомендуєте нас другу, від 0 до 10?» NPS = % тих, хто поставив 9–10, мінус % тих, хто 0–6. Одне питання раз на квартал — і видно, хто з клієнтів на межі.'),
('negotiation', 'BATNA — твій запасний план', 'Найкраща альтернатива, якщо угоди не буде (з книги «Шлях до згоди» Фішера і Юрі). Хто має сильнішу альтернативу — той спокійніший і сильніший у переговорах. Перед розмовою запиши свою і прикинь їхню.'),
('negotiation', 'ZOPA — зона угоди', 'Проміжок між мінімумом, на який згоден продавець, і максимумом, який готовий дати покупець. Якщо проміжку нема — торгуватись про ціну марно, міняй обсяг чи умови.'),
('negotiation', 'Якір першої цифри', 'Перша названа цифра тягне всю розмову до себе — це ефект якоря (Канеман і Тверскі). Знаєш ринок — називай першим, трохи вище цілі і з поясненням, з чого вона складається.'),
('negotiation', 'Назвав ціну — замовкни', 'Після ціни не виправдовуйся і не пропонуй знижку сам. Пауза незручна, але той, хто перший заговорить, зазвичай поступається.'),
('negotiation', 'Нічого безкоштовно', 'Кожна поступка — в обмін на щось: «Можу дати −10%, якщо оплата за 3 місяці наперед». Інакше людина вчиться, що тиснути вигідно.'),
('negotiation', 'Називай емоцію', 'Прийом Кріса Восса («Ніколи не йди на компроміс»): «Схоже, вас турбує, що бюджет піде в нікуди». Коли емоцію назвали вголос, напруга падає, і людина сама розповідає більше.'),
('negotiation', 'Калібровані питання', 'Замість «ні» — «Як мені це зробити в такий бюджет?» Питання «як» і «що» змушують іншу сторону самій шукати рішення і бачити твої обмеження. Теж від Восса.'),
('negotiation', 'Письмовий підсумок', 'Після дзвінка — 3–5 рядків у чат: що вирішили, хто що робить, до коли. Через місяць це знімає 90% суперечок «ми так не домовлялись».'),
('sales', 'Швидкість відповіді на лід', 'Часто цитоване дослідження Lead Response (MIT, 2007): якщо подзвонити за 5 хвилин, шанс кваліфікувати лід у рази вищий, ніж за 30. Перше, що варто перевірити в клієнта, — скільки минає від заявки до дзвінка.'),
('sales', 'SPIN — продаж питаннями', 'Ніл Рекхем: Ситуація → Проблема → Наслідки → Вигода. Великі угоди закриває не той, хто красиво презентує, а той, хто спитав: «А що буде, якщо це не вирішити ще пів року?»'),
('sales', '«Так, і…» замість «так, але…»', '«Але» перекреслює все сказане до нього. «Так, і саме тому пропоную…» тримає людину на твоєму боці.'),
('sales', 'Прослухай 10 дзвінків', 'Перш ніж піднімати бюджет на рекламу, послухай 10 записів дзвінків менеджера. Дуже часто ліди нормальні, а гроші губляться на обробці.'),
('sales', 'Угоди нема в CRM — її нема', 'Головна цифра відділу продажів — конверсія між етапами воронки. Знайди етап з найбільшим провалом і працюй тільки з ним, поки не підтягнеш.'),
('sales', 'Продати своїм дешевше', 'Продати додаткову послугу існуючому клієнту зазвичай набагато дешевше, ніж знайти нового: довіра вже є. Раз на квартал дивись, що ще можна запропонувати кожному.'),
('marketing', 'Оффер важливіший за картинку', 'Сильна пропозиція = що я отримаю + чому саме зараз + чому вам вірити. Гарний креатив не витягне слабкий оффер, а сильний оффер працює навіть у простій картинці.'),
('marketing', 'Соціальний доказ', 'Принцип Чалдіні: люди дивляться, що роблять інші. Кейс «було → стало → за скільки» з цифрами працює сильніше за «ми професіонали з досвідом».'),
('marketing', 'Взаємність', 'Ще з Чалдіні: дай корисне першим — короткий аудит, план на сторінку, розбір реклами. Людині хочеться віддячити, і шанс угоди росте.'),
('marketing', '«Правило 7 дотиків» — не наука', 'Це маркетингова приказка, а не дослідження. Суть правдива: до покупки людині потрібно кілька контактів з брендом. Тому ретаргет і контент працюють разом з лідогенерацією.'),
('ads', 'Фаза навчання Meta', 'Групі оголошень потрібно близько 50 оптимізаційних подій за 7 днів, щоб вийти з навчання. Різкі зміни бюджету, аудиторії чи креативу запускають навчання заново — міняй рідше і пачками.'),
('ads', 'Частота як сигнал', 'Коли частота на холодну аудиторію росте (орієнтир 3–4 за тиждень), а CTR падає — креатив вигорає, і ліди дорожчають. Час на нові креативи, а не на новий бюджет.'),
('ads', 'Де ламається: креатив чи сайт', 'CTR низький — проблема в креативі або оффері. CTR нормальний, а лідів нема — проблема на сайті чи у формі. Так за хвилину знаходиш, куди копати.'),
('ads', 'Перші 3 секунди відео', 'Hook rate — частка показів, де відео дивились хоча б 3 секунди. Саме перший кадр вирішує, чи побачать решту. Тестуй різні початки з тим самим відео.'),
('ads', 'Лід-форма: обсяг чи намір', 'У лід-формах Meta є тип «Вища намірність»: додає екран перевірки перед відправкою. Лідів менше, але сміття теж менше. Якщо менеджери скаржаться на якість — спробуй його.'),
('psychology', 'Ефект приманки', 'Третій, свідомо гірший варіант робить потрібний привабливішим. Пакети «Базовий / Оптимальний / Преміум» — більшість обирає середній. Став у середину те, що хочеш продати.'),
('psychology', 'Ефект IKEA', 'Люди більше цінують те, у що вклали свою працю. Залучай клієнта до стратегії (хай допише, оцінить, обере) — потім він сам її захищає.'),
('psychology', 'Пастка вкладених грошей', 'Sunk cost: продовжувати, бо «вже стільки вклали». Рішення про кампанію чи підрядника приймай тільки по тому, що буде далі, а не по тому, що вже витрачено.'),
('psychology', 'Ефект Зейгарнік', 'Незавершені справи пам’ятаються краще і «висять» у голові. Тому записана задача знімає напругу — для цього і є система.'),
('business', 'Парето в клієнтах', 'Часто меншість клієнтів дає більшість прибутку, а кілька — забирають непропорційно часу. Порахуй прибуток на годину роботи по кожному: цифра часто здивує.'),
('business', 'Ціна — найсильніший важіль', 'Дослідження McKinsey: +1% до ціни при тих самих продажах дає приблизно +8–11% операційного прибутку — більше, ніж +1% обсягу. Підняти ціну на 10% часто простіше, ніж знайти на 10% більше клієнтів.'),
('business', 'Абонплата + результат', 'Проєкт дає разові гроші, абонплата — стабільність. Сильна схема для агенції: запуск як проєкт + підтримка помісячно + бонус за результат.'),
('fact', 'Закон Паркінсона', 'Робота заповнює весь час, який на неї відведено. Даєш собі тиждень на звіт — він займе тиждень. Короткі чесні дедлайни — і задача стискається.'),
('fact', 'Матриця Ейзенхауера', 'Важливе і термінове — роби зараз; важливе, не термінове — планувати (тут ріст бізнесу); термінове, не важливе — делегуй; ні те, ні те — викинь. Більшість росту живе в другому квадраті.');
INSERT INTO changelog (title, body, created_at) VALUES
('Поради від Джері',
